{{!-- Styling parameters: class, titleClass, gridClass, cardClass, cardTitleClass, imageClass, descriptionClass --}}
{{#with this as |ghostcnStyles|}}
{{#if posts}}
<section class="ghcn-post-grid{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}" aria-label="Posts">
  {{#if heading}}<h2 class="ghcn-post-grid__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">{{heading}}</h2>{{/if}}
  <div class="ghcn-post-grid__grid{{#if ghostcnStyles.gridClass}} {{ghostcnStyles.gridClass}}{{/if}}">{{#foreach posts}}
    {{> "components/post-card" class=ghostcnStyles.cardClass titleClass=ghostcnStyles.cardTitleClass imageClass=ghostcnStyles.imageClass descriptionClass=ghostcnStyles.descriptionClass}}
  {{/foreach}}</div>
</section>
{{else}}{{#if emptyText}}<section class="ghcn-post-grid{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}"><p class="ghcn-post-grid__empty">{{emptyText}}</p></section>{{/if}}{{/if}}
{{/with}}

.ghcn-post-grid { box-sizing: border-box; min-width: 0; margin-block: var(--ghcn-section-space, clamp(24px, 4vw, 48px)); font-family: inherit; font-size: var(--ghcn-text-body, 16px); line-height: 1.5; color: var(--foreground); width: min(100% - 32px, 1152px); margin-inline: auto; }
.ghcn-post-grid__title { font-size: var(--ghcn-title-section, clamp(24px, 3vw, 32px)); font-weight: 700; line-height: 1.18; letter-spacing: -.035em; text-wrap: balance; margin: 0 0 var(--ghcn-section-gap, 20px); }
.ghcn-post-grid__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr)); gap: var(--ghcn-grid-gap, 16px); }
.ghcn-post-grid__grid > * { min-width: 0; }
.ghcn-post-grid__empty { color: var(--muted-foreground); }
